// ---- Matematik dinamik soru üreteci (TYMM ünitelerine göre) ----
function rnd(a, b) {
  return Math.floor(Math.random() * (b - a + 1)) + a;
}

function karistir(arr) {
  const d = arr.slice();
  for (let i = d.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [d[i], d[j]] = [d[j], d[i]];
  }
  return d;
}

function secenekYap(dogru, yanlislar) {
  const set = [String(dogru)];
  yanlislar.forEach((x) => {
    const v = String(x);
    if (!set.includes(v) && set.length < 4) set.push(v);
  });
  let deneme = 0;
  while (set.length < 4 && deneme < 200) {
    deneme++;
    const aday = String(rnd(2, 99));
    if (!set.includes(aday)) set.push(aday);
  }
  const secenekler = karistir(set);
  return { secenekler, dogruIdx: secenekler.indexOf(String(dogru)) };
}

function matematikSoru(sinif, unite, zorluk) {
  const z = zorluk === "zor";
  let s = "2 + 2 kaçtır?";
  let d = "4";
  let y = ["5", "3", "6"];

  if (sinif === 5) {
    if (unite === 1) {
      if (!z) { const a = rnd(120, 950), b = rnd(15, 90); d = String(a + b); s = `${a} + ${b} kaçtır?`; y = [String(a + b + 10), String(a + b - 10), String(a + b + 1)]; }
      else { const n = rnd(1000, 9999); const rakam = String(n)[1]; d = rakam; s = `${n} sayısının yüzler basamağındaki rakam kaçtır?`; y = [String((+rakam + 1) % 10), String((+rakam + 5) % 10), String(+rakam === 0 ? 9 : +rakam - 1)]; }
    } else if (unite === 2) {
      if (!z) { const p = rnd(3, 9); d = `${p}/${p}`; s = `${p} dilim pastanın ${p} dilimini yiyen bir kişi ne kadarını yer?`; d = "Tamamını (1)"; s = "Bir pastanın tamamı yenirse kesir olarak hangisi doğrudur?"; y = ["1/2", "1/4", "0"]; }
      else { const a = rnd(1, 4), b = rnd(5, 9); d = String((a + b)); s = `${a}/4 + ${b}/4 işleminin sonucu kaçtır?`; y = [String(a + b + 1), String(a * b), String(a + b - 1)]; }
    } else if (unite === 3) {
      if (!z) { const a = rnd(2, 6), b = rnd(2, 6); d = String(a * b); s = `${a} × ${b} kaçtır?`; y = [String(a * b + a), String(a + b), String(a * b - 1)]; }
      else { const k = rnd(2, 5); d = String(4 * k); s = `Kuralı 4 × n olan örüntünün ${k}. terimi kaçtır?`; y = [String(4 * k + 4), String(4 + k), String(4 * k - 4)]; }
    } else if (unite === 4) {
      if (!z) { d = "90"; s = "Dik açı kaç derecedir?"; y = ["45", "180", "60"]; }
      else { const a = rnd(30, 80); d = String(180 - a - 50); s = `Bir üçgenin iki açısı ${a}° ve 50° ise üçüncü açı kaç derecedir?`; y = [String(180 - a), String(180 - 50), String(a + 50)]; }
    } else if (unite === 5) {
      if (!z) { const a = rnd(4, 12), b = rnd(3, 9); d = String(2 * (a + b)); s = `Kenarları ${a} cm ve ${b} cm olan dikdörtgenin çevresi kaç cm'dir?`; y = [String(a * b), String(a + b), String(2 * a + b)]; }
      else { const a = rnd(4, 12), b = rnd(3, 9); d = String(a * b); s = `Dikdörtgenin alanı: ${a} cm × ${b} cm = ?`; y = [String(2 * (a + b)), String(a + b), String(a * b + a)]; }
    } else if (unite === 6) {
      if (!z) { const t = [rnd(4, 10), rnd(4, 10), rnd(4, 10)]; const ort = Math.round((t[0] + t[1] + t[2]) / 3); d = String(ort); s = `${t.join(", ")} sayılarının ortalaması kaçtır?`; y = [String(ort + 1), String(ort - 1), String(t[0])]; }
      else { const t = [3, 5, 5, 7, 8]; d = "5"; s = `${t.join(", ")} verisinde en çok tekrar eden sayı (mod) kaçtır?`; y = ["3", "8", "7"]; }
    } else {
      if (!z) { d = "1/6"; s = "Bir zar atıldığında 3 gelme olasılığı kaçtır?"; y = ["1/3", "1/2", "3/6"]; }
      else { d = "1/2"; s = "Bir madenî para atıldığında tura gelme olasılığı kaçtır?"; y = ["1/4", "1/3", "1"]; }
    }
  } else if (sinif === 6) {
    if (unite === 1) {
      if (!z) { const a = rnd(12, 30), b = rnd(3, 9); d = String(a * b); s = `${a} × ${b} kaçtır?`; y = [String(a * b + a), String(a + b), String(a * b - b)]; }
      else { const n = rnd(12, 40); const bolen = [2, 3, 4, 5, 6].filter((x) => n % x === 0); d = bolen.length ? String(bolen[0]) : "2"; s = `${n} sayısının en küçük çarpanı olan (1 hariç) sayı hangisidir?`; y = ["1", String(n), String(n + 1)]; }
    } else if (unite === 2) {
      if (!z) { const a = rnd(1, 3), b = rnd(1, 3), c = rnd(4, 9); d = `${a * c + b}/${c}`; s = `${a} + ${b}/${c} işleminin sonucu hangisidir?`; y = [`${a + b}/${c}`, `${a * c + b}/${c + 1}`, `${b}/${c}`]; }
      else { const a = rnd(2, 8), b = rnd(2, 5); d = String(a * b); s = `${a} : ${b} oranı için ${a} sayısı ${b} sayısının kaç katıdır?`; d = "3"; s = "12'nin 4'e oranı kaçtır?"; y = ["2", "4", "8"]; }
    } else if (unite === 3) {
      if (!z) { const x = rnd(2, 6); d = String(x + 4); s = `x + 4 = ${x + 4} ise x kaçtır?`; y = [String(x + 8), String(x), "4"]; }
      else { const a = rnd(2, 5); d = String(a * 3); s = `3x = ${a * 3} ise x kaçtır?`; y = [String(a * 9), String(a + 3), "3"]; }
    } else if (unite === 4) {
      if (!z) { d = "180"; s = "Üçgenin iç açıları toplamı kaç derecedir?"; y = ["90", "360", "270"]; }
      else { d = "360"; s = "Bir dörtgenin iç açıları toplamı kaç derecedir?"; y = ["180", "540", "90"]; }
    } else if (unite === 5) {
      if (!z) { const a = rnd(3, 9); d = String(a * a); s = `Kenar uzunluğu ${a} cm olan karenin alanı kaç cm²'dir?`; y = [String(4 * a), String(2 * a), String(a + a)]; }
      else { const a = rnd(2, 5), b = rnd(2, 4), c = rnd(2, 3); d = String(a * b * c); s = `${a} cm × ${b} cm × ${c} cm boyutlarındaki dikdörtgen prizmanın hacmi kaç cm³'tür?`; y = [String(2 * (a + b + c)), String(a + b + c), String(a * b + c)]; }
    } else if (unite === 6) {
      if (!z) { const t = [4, 6, 8, 10]; d = "7"; s = `${t.join(", ")} verisinin ortalaması kaçtır?`; y = ["6", "8", "7.5"]; }
      else { const t = [3, 4, 4, 6, 8]; d = "4"; s = `${t.join(", ")} verisinin en çok tekrar eden değeri (mod) kaçtır?`; y = ["3", "8", "6"]; }
    } else {
      if (!z) { d = "0.25"; s = "Bir torbada 4 top var, 1'i kırmızı. Rastgele çekilenin kırmızı olma olasılığı kaçtır?"; y = ["0.5", "0.75", "1"]; }
      else { d = "50%"; s = "Bir zar atıldığında çift sayı gelme olasılığı yüzde kaçtır?"; y = ["25%", "33%", "75%"]; }
    }
  } else if (sinif === 7) {
    if (unite === 1) {
      if (!z) { const a = rnd(-10, 10), b = rnd(-6, 6); d = String(a + b); s = `${a} + (${b}) kaçtır?`; y = [String(a - b), String(-a - b), String(Math.abs(a + b))]; }
      else { const a = rnd(-6, 6), b = rnd(-5, 5); d = String(a * b); s = `${a} × (${b}) kaçtır?`; y = [String(a * b + 4), String(-a * b), String(a - b)]; }
    } else if (unite === 2) {
      if (!z) { d = String(15); s = "20 sayısının %75'i kaçtır?"; y = ["10", "25", "5"]; }
      else { d = "200"; s = "500 TL'lik ürün %40 indirimle kaç TL olur?"; y = ["100", "150", "250"]; }
    } else if (unite === 3) {
      if (!z) { const x = rnd(3, 8); d = String(2 * x + 3); s = `2x + 3 ifadesinde x = ${x} ise sonuç kaçtır?`; y = [String(2 * x + 5), String(x + 3), String(3 * x)]; }
      else { const b = rnd(1, 8); d = String(b + 1); s = `2x − 2 = ${2 * b} ise x kaçtır?`; y = [String(b), String(b + 2), String(2 * b)]; }
    } else if (unite === 4) {
      if (!z) { d = "Aynalama"; s = "Bir şeklin bir doğruya göre simetriği alınırsa hangi dönüşüm uygulanmış olur?"; y = ["Öteleme", "Döndürme", "Yaklaştırma"]; }
      else { d = "180°"; s = "Dönme hareketinde yarım tur kaç derecedir?"; y = ["90°", "270°", "45°"]; }
    } else if (unite === 5) {
      if (!z) { const a = rnd(4, 10), b = rnd(3, 8); d = String(a * b); s = `Tabanı ${a} cm, yüksekliği ${b} cm olan paralelkenarın alanı kaç cm²'dir?`; y = [String(a * b / 2), String(2 * (a + b)), String(a + b)]; }
      else { const a = rnd(5, 12), b = rnd(3, 8); d = String(a * b); s = `Tabanı ${a} cm, yüksekliği ${b} cm olan üçgenin alanı kaç cm²'dir?`; y = [String(a * b), String(2 * (a + b)), String(a + b)]; }
    } else if (unite === 6) {
      if (!z) { const r = rnd(3, 7); d = String(Math.round(2 * 22 * r / 7)); s = `Yarıçapı ${r} cm olan çemberin uzunluğu (π ≈ 22/7) yaklaşık kaç cm'dir?`; y = [String(Math.round(22 * r / 7)), String(2 * r), String(Math.round(22 * r))]; }
      else { const r = rnd(2, 5); d = String(Math.round(3 * r * r)); s = `Yarıçapı ${r} cm olan dairenin alanı (π ≈ 3) yaklaşık kaç cm²'dir?`; y = [String(Math.round(2 * 3 * r)), String(3 * r), String(Math.round(3 * r * r) + 3)]; }
    } else if (unite === 7) {
      if (!z) { d = "180"; s = "Üçgenin iç açıları toplamı kaç derecedir?"; y = ["360", "90", "270"]; }
      else { const n = 5; d = String((n - 2) * 180); s = "Beşgenin iç açıları toplamı kaç derecedir?"; y = ["540", "360", "720"]; }
    } else if (unite === 8) {
      if (!z) { const t = [5, 7, 9, 11]; d = "8"; s = `${t.join(", ")} verisinin ortalaması kaçtır?`; y = ["7", "9", "10"]; }
      else { d = "Daire grafiği"; s = "Bir bütünün parçalarını oransal olarak gösteren grafik türü hangisidir?"; y = ["Sütun grafiği", "Çizgi grafiği", "Nokta grafiği"]; }
    } else {
      if (!z) { d = "1/6"; s = "Bir zar atıldığında 5 gelme olasılığı kaçtır?"; y = ["1/5", "1/3", "5/6"]; }
      else { d = "3/6"; s = "Bir zar atıldığında 3'ten büyük sayı gelme olasılığı kaçtır?"; y = ["1/6", "2/6", "4/6"]; }
    }
  } else {
    if (unite === 1) {
      if (!z) { d = "64"; s = "2'nin 6. kuvveti (2⁶) kaçtır?"; y = ["12", "32", "36"]; }
      else { const a = rnd(2, 6); d = String(a * a); s = `√${a * a} işleminin sonucu kaçtır?`; y = [String(a * 2), String(a + a), String(a * a + a)]; }
    } else if (unite === 2) {
      if (!z) { const x = rnd(2, 6); d = String(x + 5); s = `x + 5 = ${x + 5} ise x kaçtır?`; y = [String(x + 10), String(x), "5"]; }
      else { const a = rnd(2, 5); d = String(a * 3); s = `3x = ${a * 3} ise x kaçtır?`; y = [String(a * 9), String(a + 3), "3"]; }
    } else if (unite === 3) {
      if (!z) { d = "180"; s = "Üçgenin iç açıları toplamı kaç derecedir?"; y = ["90", "360", "270"]; }
      else { d = "Benzer"; s = "Açıları eşit, kenarları orantılı olan iki çokgen için hangisi söylenir?"; y = ["Eş", "Farklı", "Dik"]; }
    } else if (unite === 4) {
      if (!z) { const a = rnd(4, 10); d = String(a * a); s = `Kenarı ${a} cm olan karenin alanı kaç cm²'dir?`; y = [String(4 * a), String(2 * a), String(a + a)]; }
      else { const a = rnd(2, 4); d = String(a * a * a); s = `Bir küpün kenarı ${a} cm ise hacmi kaç cm³'tür?`; y = [String(6 * a * a), String(3 * a), String(a * a)]; }
    } else if (unite === 5) {
      if (!z) { d = "Öteleme"; s = "Bir şeklin konumunun değişmeden yer değiştirmesine ne denir?"; y = ["Yansıma", "Döndürme", "Yaklaştırma"]; }
      else { d = "Yansıma"; s = "Bir şeklin bir doğruya göre simetriği hangi dönüşümdür?"; y = ["Öteleme", "Döndürme", "Genişletme"]; }
    } else if (unite === 6) {
      if (!z) { const t = [3, 5, 7, 9]; d = "6"; s = `${t.join(", ")} verisinin ortalaması kaçtır?`; y = ["5", "7", "8"]; }
      else { const t = [2, 4, 4, 6, 9]; d = "4"; s = `${t.join(", ")} verisinin modu (en çok tekrar eden) kaçtır?`; y = ["2", "6", "9"]; }
    } else {
      if (!z) { d = "1/2"; s = "Bir madenî para atıldığında yazı gelme olasılığı kaçtır?"; y = ["1/4", "1/3", "1"]; }
      else { d = "1/3"; s = "Bir zar atıldığında 1 veya 2 gelme olasılığı kaçtır?"; y = ["1/6", "1/2", "2/6"]; }
    }
  }

  return { s, ...secenekYap(d, y) };
}

// ---- Soru havuzu ----
function soruHavuzu(sinif, dersSlug, uniteNo, zorluk, kullanilan) {
  const banka = (SORULAR[sinif] && SORULAR[sinif][dersSlug]) || [];
  const oneCikan = [];
  const digerleri = [];

  banka.forEach((q) => {
    const [u, z, soru, ...rest] = q;
    if (z !== zorluk) return;
    if (kullanilan.includes(soru)) return;
    const karisik = karistir(rest);
    const obj = { s: soru, secenekler: karisik, dogruIdx: karisik.indexOf(rest[0]) };
    if (u === uniteNo) oneCikan.push(obj);
    else digerleri.push(obj);
  });

  const liste = oneCikan.length > 0 ? oneCikan.concat(oneCikan.length < 3 ? digerleri : []) : digerleri;
  if (liste.length === 0) return null;
  return liste[Math.floor(Math.random() * liste.length)];
}

function soruUret(sinif, dersSlug, uniteNo, zorluk, kullanilan) {
  if (dersSlug === "matematik") {
    return matematikSoru(sinif, uniteNo, zorluk);
  }
  return soruHavuzu(sinif, dersSlug, uniteNo, zorluk, kullanilan || []);
}
